commit 92aed8bc2c9bd107f6b1d8835f5d1eab4f9b9735
Author: Tim Rühsen <tim.ruehsen@gmx.de>
Date:   Tue Jun 23 22:01:04 2020 +0200

    * src/options.c: Fix crash introduced in fa3c71c85

diff --git a/src/options.c b/src/options.c
index 1f8e73f5..a10610f6 100644
--- a/src/options.c
+++ b/src/options.c
@@ -3040,9 +3040,9 @@ static void WGET_GCC_NONNULL_ALL get_config_files(const char *config_home, const
        // First add the Global Wget2rc file.
        if ((env = getenv ("SYSTEM_WGET2RC")) && *env) {
                config.system_config = wget_strdup(env);
-       } else {
-               if (config.system_config && access(config.system_config, R_OK) != 0)
-                       config.system_config = NULL;
+       } else if (config.system_config) {
+               if (access(config.system_config, R_OK) != 0)
+                       xfree(config.system_config);
        }

        if ((env = getenv("WGET2RC")) && *env) {
@@ -3242,6 +3242,7 @@ int init(int argc, const char **argv)
        config.secure_protocol = wget_strdup(config.secure_protocol);
        config.ca_directory = wget_strdup(config.ca_directory);
        config.default_page = wget_strdup(config.default_page);
+       config.system_config = wget_strdup(config.system_config);

        log_init();

commit 717766da8926e36cf86015c4a49554baa854e8e6
Author: Bruno Haible <bruno@clisp.org>
Date:   Fri Jan 17 21:56:01 2020 +0100

    glob: Fix use-after-free bug.

    Reported by Tim Rühsen <tim.ruehsen@gmx.de> in
    <https://lists.gnu.org/archive/html/bug-gnulib/2020-01/msg00102.html>.

    * lib/glob.c (__glob): Delay freeing dirname until after the use of
    end_name.

diff --git a/lib/glob.c b/lib/glob.c
index a67cbb67e0..add5d939d2 100644
--- a/lib/glob.c
+++ b/lib/glob.c
@@ -843,10 +843,11 @@ __glob (const char *pattern, int flags, int (*errfunc) (const char *, int),
               {
                 size_t home_len = strlen (p->pw_dir);
                 size_t rest_len = end_name == NULL ? 0 : strlen (end_name);
+                /* dirname contains end_name; we can't free it now.  */
+                char *prev_dirname =
+                  (__glibc_unlikely (malloc_dirname) ? dirname : NULL);
                 char *d;

-                if (__glibc_unlikely (malloc_dirname))
-                  free (dirname);
                 malloc_dirname = 0;

                 if (glob_use_alloca (alloca_used, home_len + rest_len + 1))
@@ -857,6 +858,7 @@ __glob (const char *pattern, int flags, int (*errfunc) (const char *, int),
                     dirname = malloc (home_len + rest_len + 1);
                     if (dirname == NULL)
                       {
+                        free (prev_dirname);
                         scratch_buffer_free (&pwtmpbuf);
                         retval = GLOB_NOSPACE;
                         goto out;
@@ -868,6 +870,8 @@ __glob (const char *pattern, int flags, int (*errfunc) (const char *, int),
                   d = mempcpy (d, end_name, rest_len);
                 *d = '\0';

+                free (prev_dirname);
+
                 dirlen = home_len + rest_len;
                 dirname_modified = 1;
               }
